from __future__ import annotations
import json
from pathlib import Path

HTML=Path('docs/index.html')
DATA=Path('data/dashboard/wnba_injury_intelligence.json')

STYLE='''<style id="v5-injury-intelligence-style">
.injuryGrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.injuryCard{border:1px solid #263854;border-radius:16px;padding:16px;background:#091321}.injuryRow{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #1c2a40}.injuryRow:last-child{border-bottom:0}.injuryBadge{border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800}.injury-out{color:#ff7188;border:1px solid #7b2639;background:#260d16}.injury-questionable{color:#ffd06b;border:1px solid #70551f;background:#241b08}.injury-beneficiary{color:#3de6b0;border:1px solid #17634e;background:#082019}.injury-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:14px 0}.injury-kpi{border:1px solid #263854;border-radius:14px;padding:14px;background:#08111f}.injury-kpi b{display:block;font-size:25px;margin-top:5px}.injuryDelta{font-weight:800}.injury-source{font-size:11px;color:#8392ad}.injuryFresh{color:#3de6b0}.injuryAging{color:#ffd06b}.injuryStale{color:#ff7188}.injuryLeaderboards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px;margin:14px 0}.injuryImpact{border:1px solid #2c4262;border-radius:12px;padding:10px;margin-top:10px;background:#07101d}.injuryImpactTitle{display:flex;justify-content:space-between;gap:10px;align-items:center}.injuryMetrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:8px;font-size:11px;color:#aab8d1}.bestInjuryContext{margin-top:10px;padding:10px;border:1px solid #17634e;border-radius:12px;background:#071b18}.bestInjuryContext.warn{border-color:#70551f;background:#211908}.bestInjuryHead{display:flex;justify-content:space-between;gap:8px;align-items:center;font-weight:800}.bestInjuryGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:8px;font-size:11px}.bestInjuryPositive{color:#3de6b0}.bestInjuryNegative{color:#ff7188}.bestInjuryNeutral{color:#ffd06b}
</style>'''

SCRIPT='''<script id="v5-injury-intelligence-script">(function(){
const D=window.WNBA_INJURY_DATA||{};const arr=v=>Array.isArray(v)?v:[];const esc=v=>window.E?window.E(v):String(v??'');const norm=v=>String(v??'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\\s+/g,' ').trim();
function badge(s){s=String(s||'UNKNOWN').toUpperCase();const c=s==='OUT'||s==='DOUBTFUL'?'injury-out':s==='QUESTIONABLE'?'injury-questionable':'injury-beneficiary';return `<span class="injuryBadge ${c}">${esc(s)}</span>`}
function freshness(){const stamp=D.generated_at_utc?Date.parse(D.generated_at_utc):NaN;const mins=Number.isFinite(stamp)?Math.max(0,Math.round((Date.now()-stamp)/60000)):Number(D.freshness_minutes||999);return {mins,label:mins<30?'FRESH':mins<=90?'AGING':'STALE',cls:mins<30?'injuryFresh':mins<=90?'injuryAging':'injuryStale'}}
window.injuryIntelligence=function(){const injuries=arr(D.injuries),adj=arr(D.adjustments),impacts=arr(D.team_impacts);const out=injuries.filter(x=>['OUT','DOUBTFUL'].includes(String(x.severity||'').toUpperCase()));const q=injuries.filter(x=>String(x.severity||'').toUpperCase()==='QUESTIONABLE');const boosts=adj.filter(x=>String(x.severity||'').toUpperCase()==='BENEFICIARY').sort((a,b)=>Number(b.minutes_delta||0)-Number(a.minutes_delta||0));const usage=[...boosts].sort((a,b)=>Number(b.usage_delta||0)-Number(a.usage_delta||0));const teams=[...new Set([...(D.teams||[]),...injuries.map(x=>x.team)])];const f=freshness();return `<div class="section"><h2 class="mono">Injury Intelligence</h2><div class="small mono">Official availability, minutes redistribution and projection impact for ${esc(D.target_date||'current slate')}.</div><div class="injury-kpis"><div class="injury-kpi"><span class="small mono">Feed status</span><b class="${f.cls}">${f.label}</b><span class="small mono">${f.mins} min</span></div><div class="injury-kpi"><span class="small mono">Out / doubtful</span><b>${out.length}</b></div><div class="injury-kpi"><span class="small mono">Questionable</span><b>${q.length}</b></div><div class="injury-kpi"><span class="small mono">Minutes boosts</span><b>${boosts.length}</b></div></div><div class="injuryLeaderboards"><div class="injuryCard"><h3>Biggest Injury Winners</h3>${boosts.slice(0,8).map((x,i)=>`<div class="injuryRow"><div><b>${i+1}. ${esc(x.player)}</b><div class="injury-source">${esc(x.team)}</div></div><div class="injuryDelta">+${Number(x.minutes_delta||0).toFixed(1)} min</div></div>`).join('')||'<div class="small mono">No verified boosts.</div>'}</div><div class="injuryCard"><h3>Largest Usage Boosts</h3>${usage.slice(0,8).map((x,i)=>`<div class="injuryRow"><div><b>${i+1}. ${esc(x.player)}</b><div class="injury-source">${esc(x.team)}</div></div><div class="injuryDelta">+${Number(x.usage_delta||0).toFixed(1)}%</div></div>`).join('')||'<div class="small mono">No verified usage changes.</div>'}</div></div><div class="injuryGrid">${teams.map(team=>{const rows=injuries.filter(x=>x.team===team);const b=boosts.filter(x=>x.team===team).slice(0,6);const impact=impacts.find(x=>x.team===team)||{};return `<div class="injuryCard"><h3>${esc(team)}</h3><div class="injuryImpact"><div class="injuryImpactTitle"><b>Team impact</b><span class="injuryBadge ${impact.impact_level==='HIGH'?'injury-out':impact.impact_level==='MED'?'injury-questionable':'injury-beneficiary'}">${esc(impact.impact_level||'LOW')}</span></div><div class="injuryMetrics"><span>Missing minutes: ${esc(impact.missing_minutes??0)}</span><span>Reallocated: ${esc(impact.minutes_reallocated??0)}</span></div></div>${rows.length?rows.map(x=>`<div class="injuryRow"><div><b>${esc(x.player)}</b><div class="injury-source">${esc(x.injury_type||x.detail||'')}</div></div>${badge(x.severity||x.status)}</div>`).join(''):'<div class="small mono">No listed injuries.</div>'}${b.length?`<h4 class="mono">Minutes redistribution</h4>${b.map(x=>`<div class="injuryRow"><div><b>${esc(x.player)}</b><div class="injury-source">${esc(x.base_minutes)} → ${esc(x.projected_minutes)} min · usage +${Number(x.usage_delta||0).toFixed(1)}%</div></div><div class="injuryDelta">+${Number(x.minutes_delta||0).toFixed(1)}</div></div>`).join('')}`:''}</div>`}).join('')}</div><div class="small mono" style="margin-top:14px">Source: ${esc((injuries[0]||{}).source||'verified injury feed')} · Generated ${esc(D.generated_at_utc||'')}</div></div>`};
function findAdjustment(player){const key=norm(player);return arr(D.adjustments).find(x=>norm(x.player)===key)}
function smallestCard(root,player){const key=norm(player);let candidates=[...root.querySelectorAll('div,article,section,li')].filter(el=>norm(el.textContent).includes(key));candidates=candidates.filter(el=>!el.querySelector('.bestInjuryContext'));candidates.sort((a,b)=>a.textContent.length-b.textContent.length);return candidates.find(el=>el.textContent.length<1600)||null}
function contextHtml(adj){const status=String(adj.severity||'UNKNOWN').toUpperCase();const warning=['QUESTIONABLE','DOUBTFUL','UNKNOWN'].includes(status);const factor=Number(adj.projection_factor||1);const projPct=(factor-1)*100;return `<div class="bestInjuryContext ${warning?'warn':''}"><div class="bestInjuryHead"><span>Injury-adjusted</span>${badge(status)}</div><div class="bestInjuryGrid"><span>Minutes</span><b>${esc(adj.base_minutes)} → ${esc(adj.projected_minutes)} (${Number(adj.minutes_delta||0)>=0?'+':''}${Number(adj.minutes_delta||0).toFixed(1)})</b><span>Usage change</span><b class="${Number(adj.usage_delta||0)>0?'bestInjuryPositive':'bestInjuryNeutral'}">${Number(adj.usage_delta||0)>=0?'+':''}${Number(adj.usage_delta||0).toFixed(1)}%</b><span>Projection impact</span><b class="${projPct>0?'bestInjuryPositive':projPct<0?'bestInjuryNegative':'bestInjuryNeutral'}">${projPct>=0?'+':''}${projPct.toFixed(1)}%</b><span>Availability risk</span><b>${warning?'REVIEW':'VERIFIED'}</b></div><div class="injury-source" style="margin-top:7px">${esc(adj.detail||'Current injury and lineup redistribution applied.')}</div></div>`}
function decorateBest(){const root=document.getElementById('root');if(!root)return;for(const adj of arr(D.adjustments)){if(!adj.player)continue;const card=smallestCard(root,adj.player);if(card)card.insertAdjacentHTML('beforeend',contextHtml(adj))}}
function installBestHook(){if(window.__injuryBestHook)return;const original=window.render;if(typeof original!=='function'){setTimeout(installBestHook,50);return}window.__injuryBestHook=true;window.render=function(view){const result=original.apply(this,arguments);const resolved=view||'games';if(resolved==='best')setTimeout(decorateBest,0);return result}}
installBestHook();
})();</script>'''

def block_replace(text, start, end, repl):
    i=text.find(start)
    if i<0:return text
    j=text.find(end,i)
    if j<0:return text
    return text[:i]+repl+text[j+len(end):]

def main():
    if not HTML.exists(): raise SystemExit('docs/index.html missing')
    payload=json.load(DATA.open(encoding='utf-8')) if DATA.exists() else {}
    html=HTML.read_text(encoding='utf-8')
    data='<script id="v5-injury-intelligence-data">window.WNBA_INJURY_DATA='+json.dumps(payload,separators=(',',':'))+';</script>'
    for ident,content in [('v5-injury-intelligence-style',STYLE),('v5-injury-intelligence-data',data),('v5-injury-intelligence-script',SCRIPT)]:
        marker=f'id="{ident}"'
        if marker in html:
            tag='style' if 'style' in ident else 'script'
            html=block_replace(html,f'<{tag} id="{ident}">',f'</{tag}>',content)
        else:
            html=html.replace('</head>',content+'</head>') if ident.endswith('style') else html.replace('</body>',content+'</body>')
    html=html.replace("['market','Market Intelligence'],['mission'", "['market','Market Intelligence'],['injuries','Injuries'],['mission'")
    html=html.replace("else if(view==='market')html=invoke('Market Intelligence',[window.marketIntelligence]);else if(view==='mission')", "else if(view==='market')html=invoke('Market Intelligence',[window.marketIntelligence]);else if(view==='injuries')html=invoke('Injury Intelligence',[window.injuryIntelligence]);else if(view==='mission')")
    HTML.write_text(html,encoding='utf-8')
    print({'injuries':len(payload.get('injuries',[])),'adjustments':len(payload.get('adjustments',[])),'best_bet_context':True})

if __name__=='__main__': main()
